import { create } from 'zustand';

export const useStore = create((set, get) => ({
	page: 0,
	file: null,
	csv: null,
	previousPage: null,
	raportConfig: {
		title: "",
		data: [],
		charts: [],
		mode: "pdf"
	},
	setRaportTitle: (title) => set((state) => ({ raportConfig: { ...state.raportConfig, title: title } })),
	addChart: (defaultX = "", defaultY = "") => set((state) => ({
		raportConfig: {
			...state.raportConfig,
			charts: [...state.raportConfig.charts,
			{
				id: Date.now(),
				title: "",
				axisX: defaultX,
				axisY: defaultY,
				regression: false,
				determination: false,
			}]
		}
	})),
	updateChart: (index, field, value) => set((state) => {
		const updatedCharts = [...state.raportConfig.charts]
		updatedCharts[index] = { ...updatedCharts[index], [field]: value }
		return { raportConfig: { ...state.raportConfig, charts: updatedCharts } }
	}),
	removeChart: (index) => set((state) => ({
		raportConfig: { ...state.raportConfig, charts: state.raportConfig.charts.filter((_, i) => i !== index) }
	})),

	toggleData: (column, data) => set((state) => {
		const currentData = state.raportConfig.data;
		const exists = currentData.some((element) => element.column === column && element.data === data);
		let newData;
		if (exists) {
			newData = currentData.filter((element) => !(element.column === column && element.data === data));
		} else {
			newData = [...currentData, { column, data }];
		}
		return {
			raportConfig: { ...state.raportConfig, data: newData }
		};
	}),
	isChecked: (column, data) => get().raportConfig.data.some(item => item.column === column && item.data === data),

	updateRaportConfig: (newConfig) => set((state) => ({
		raportConfig: { ...state.raportConfig, ...newConfig }
	})),
	nextPage: () => set((state) => ({ page: (state.page + 1) % 3 })),
	setFile: (file) => set({ file: file }),
	setCsv: (csv) => set({ csv: csv }),
	resetApp: () => set({ page: 0, file: null, csv: null, previousPage: null }),
	switchLoading: () => set((state) => {
		if (state.page !== 3) {
			return {
				previousPage: state.page,
				page: 3
			};
		} else {
			return {
				page: state.previousPage
			};
		}
	})
}));
