import { useStore } from "../store.js"

export default function Configure() {
	const csv = useStore((state) => state.csv)
	const nextPage = useStore((state) => state.nextPage);
	const raportConfig = useStore((state) => state.raportConfig);
	const addChart = useStore((state) => state.addChart)
	const removeChart = useStore((state) => state.removeChart)
	const setRaportTitle = useStore((state) => state.setRaportTitle)
	const updateChart = useStore((state) => state.updateChart)
	const toggleData = useStore((state) => state.toggleData)
	const isChecked = useStore((state) => state.isChecked)
	const headers = csv?.meta?.fields || [];

	const chartBuilder = (chart, chartIndex) => (
		<div key={`chart${chartIndex}`} className="card bg-dark border-secondary p-3 mb-3">
			<div className="mb-3">
				<label htmlFor="chartTitle" className="form-label text-secondary small text-uppercase fw-semibold">Title</label>
				<input
					type="text"
					name="chartTitle"
					className="form-control bg-dark text-light border-secondary"
					value={chart.title}
					onChange={(e) => updateChart(chartIndex, 'title', e.target.value)}
				/>
			</div>
			<div className="mb-3">
				<label htmlFor="axisX" className="form-label text-secondary small text-uppercase fw-semibold">X Axis</label>
				<select
					name="axisX"
					className="form-select bg-dark text-light border-secondary"
					value={chart.axisX}
					onChange={(e) => updateChart(chartIndex, 'axisX', e.target.value)}
				>
					{headers.map((header) => (<option key={`${header}X`} value={header}>{header}</option>))}
				</select>
			</div>
			<div className="mb-3">
				<label htmlFor="axisY" className="form-label text-secondary small text-uppercase fw-semibold">Y Axis</label>
				<select
					name="axisY"
					className="form-select bg-dark text-light border-secondary"
					value={chart.axisY}
					onChange={(e) => updateChart(chartIndex, 'axisY', e.target.value)}
				>
					{headers.map((header) => (<option key={`${header}Y`} value={header}>{header}</option>))}
				</select>
			</div>
			<div className="mb-3 d-flex flex-column gap-2">
				<div className="form-check">
					<input
						type="checkbox"
						name="regression"
						className="form-check-input bg-dark border-secondary"
						checked={chart.regression}
						onChange={(e) => { updateChart(chartIndex, 'regression', e.target.checked) }}
					/>
					<label htmlFor="regression" className="form-check-label text-light">Add linear regression</label>
				</div>

				<div className="form-check">
					<input
						type="checkbox"
						name="determination"
						className="form-check-input bg-dark border-secondary"
						checked={chart.determination}
						onChange={(e) => { updateChart(chartIndex, 'determination', e.target.checked) }}
					/>
					<label htmlFor="determination" className="form-check-label text-light">Add determination</label>
				</div>
			</div>
			<div className="d-flex justify-content-end">
				<button className="btn btn-outline-danger btn-sm" onClick={(e) => { removeChart(chartIndex) }}>DELETE</button>
			</div>
		</div>
	)

	return (
		<div className="container flex-grow-1 d-flex align-items-center justify-content-center py-5">
			<div className="card bg-dark text-light border-secondary shadow-lg w-100" style={{ maxWidth: '900px' }}>
				<div className="card-body p-4">
					<h2 className="card-title h3 mb-4 fw-bold border-bottom border-secondary pb-2">Configure</h2>

					<h3 className="h5 text-secondary mb-3">Statistics</h3>
					<div className="table-responsive mb-4">
						<table className="table table-dark table-hover align-middle border-secondary">
							<thead>
								<tr>
									<th scope="col">Column</th>
									<th scope="col">Mean</th>
									<th scope="col">Median</th>
									<th scope="col">Deviation</th>
									<th scope="col">Error</th>
									<th scope="col">Range</th>
									<th scope="col">Uncertainty</th>
								</tr>
							</thead>
							<tbody>
								{headers.map((header, index) => (
									<tr key={`header${index}`}>
										<td>{header}</td>
										<td><input type="checkbox" className="form-check-input bg-dark border-secondary" checked={isChecked(header, 'mean')} onChange={(e) => { toggleData(header, 'mean') }} /></td>
										<td><input type="checkbox" className="form-check-input bg-dark border-secondary" checked={isChecked(header, 'median')} onChange={(e) => { toggleData(header, 'median') }} /></td>
										<td><input type="checkbox" className="form-check-input bg-dark border-secondary" checked={isChecked(header, 'deviation')} onChange={(e) => { toggleData(header, 'deviation') }} /></td>
										<td><input type="checkbox" className="form-check-input bg-dark border-secondary" checked={isChecked(header, 'error')} onChange={(e) => { toggleData(header, 'error') }} /></td>
										<td><input type="checkbox" className="form-check-input bg-dark border-secondary" checked={isChecked(header, 'range')} onChange={(e) => { toggleData(header, 'range') }} /></td>
										<td><input type="checkbox" className="form-check-input bg-dark border-secondary" checked={isChecked(header, 'uncertainty')} onChange={(e) => { toggleData(header, 'uncertainty') }} /></td>
									</tr>
								))}
							</tbody>
						</table>
					</div>

					<h3 className="h5 text-secondary mb-3">Charts</h3>
					<div className="mb-3">
						<button className="btn btn-outline-light btn-sm" onClick={() => addChart()}>Add chart</button>
					</div>

					<div id="charts" className="mb-4">
						{raportConfig.charts.map((chart, index) => chartBuilder(chart, index))}
					</div>

					<div className="d-flex justify-content-end border-top border-secondary pt-3">
						<button className="btn btn-primary px-4 fw-semibold" onClick={nextPage}>To Export</button>
					</div>
				</div>
			</div>
		</div>
	)
}
