import { useStore } from "../store";
import Papa from 'papaparse';

export default function Upload() {
	const file = useStore((state) => state.file);
	const setFile = useStore((state) => state.setFile);
	const setCsv = useStore((state) => state.setCsv);
	const switchLoading = useStore((state) => state.switchLoading);
	const nextPage = useStore((state) => state.nextPage);

	const handleSubmit = (event) => {
		event.preventDefault();
		if (!file) {
			return;
		}
		switchLoading();
		const reader = new FileReader();
		reader.onload = (e) => {
			let text = e.target.result;
			text = text.replace(/(\d+),(\d+)/g, '$1.$2');
			const parsed = Papa.parse(text, { header: true, skipEmptyLines: true, dynamicTyping: true })
			setCsv(parsed)
			switchLoading();
			nextPage();
		};
		reader.onerror = (error) => {
			console.error("Błąd podczas odczytu pliku:", error);
			switchLoading();
		}
		reader.readAsText(file);
	};
	const handleChange = (event) => {
		if (event.target.files && event.target.files[0]) {
			setFile(event.target.files[0]);
		}
	}

	return (
		<div className="container flex-grow-1 d-flex align-items-center justify-content-center py-5">
			<div className="card bg-dark text-light border-secondary shadow-lg w-100" style={{ maxWidth: '600px' }}>
				<div className="card-body p-4">
					<h2 className="card-title h3 mb-4 fw-bold border-bottom border-secondary pb-2">UPLOAD</h2>

					<form onSubmit={handleSubmit}>
						<div className="mb-3">
							<label htmlFor="file" className="form-label text-secondary small text-uppercase fw-semibold">Select file (.csv)</label>
							<input
								type="file"
								name="file"
								accept=".csv"
								className="form-control bg-dark text-light border-secondary"
								onChange={handleChange}
							/>
						</div>
						<div className="d-flex justify-content-end mt-4">
							<button type="submit" className="btn btn-primary px-4 fw-semibold">UPLOAD</button>
						</div>
					</form>
				</div>
			</div>
		</div>
	);
}
